#define CAPTURED_DATA_CAPACITY 2048U
#define DISPLAY_FRAME_BYTES 1024U
#define REFRESH_STEP_MS 10U
#define MAX_REFRESH_STEPS 200U

static oled_service_state_t g_oled_state;
static oled_dashboard_data_t g_dashboard_data;
static uint8_t g_captured_data[CAPTURED_DATA_CAPACITY];
static size_t g_captured_data_count;
static UART_HandleTypeDef *g_firmgen_uart_handle;

UART_HandleTypeDef *firmgen_uart_handle(void)
{
    return g_firmgen_uart_handle;
}

static oled_port_status_t oled_port_write_callback(uint8_t address_7bit,
                                                    uint8_t control_byte,
                                                    const uint8_t *data,
                                                    size_t length,
                                                    int cmock_num_calls)
{
    (void)address_7bit;
    (void)cmock_num_calls;

    if ((control_byte == APP_OLED_DATA_CONTROL_BYTE) && (data != NULL))
    {
        size_t available = CAPTURED_DATA_CAPACITY - g_captured_data_count;
        size_t copy_length = (length < available) ? length : available;
        if (copy_length > 0U)
        {
            memcpy(&g_captured_data[g_captured_data_count], data, copy_length);
            g_captured_data_count += copy_length;
        }
    }

    /* The OLED port status value zero is the successful status. */
    return (oled_port_status_t)0;
}

static bool finish_pending_frame(uint32_t *now_ms)
{
    for (size_t step = 0U;
         (step < MAX_REFRESH_STEPS) && g_oled_state.has_pending_frame;
         ++step)
    {
        *now_ms += REFRESH_STEP_MS;
        if (oled_service_refresh(&g_oled_state, &g_dashboard_data, *now_ms) !=
            OLED_SERVICE_STATUS_OK)
        {
            return false;
        }
    }

    return !g_oled_state.has_pending_frame;
}

void setUp(void)
{
    memset(&g_oled_state, 0, sizeof(g_oled_state));
    memset(&g_dashboard_data, 0, sizeof(g_dashboard_data));
    memset(g_captured_data, 0, sizeof(g_captured_data));
    g_captured_data_count = 0U;
    g_firmgen_uart_handle = NULL;

    oled_port_write_StubWithCallback(oled_port_write_callback);
    motion_processor_event_name_IgnoreAndReturn("");
}

void tearDown(void)
{
}

void test_FR_002_01(void)
{
    uint8_t first_frame[DISPLAY_FRAME_BYTES];
    uint32_t now_ms = 0U;

    g_dashboard_data.temperature_tenths_c = 215;
    g_dashboard_data.humidity_tenths_percent = 503U;
    g_dashboard_data.x_millig = 125;
    g_dashboard_data.y_millig = -250;
    g_dashboard_data.z_millig = 1000;
    g_dashboard_data.active_event = MOTION_EVENT_NONE;
    g_dashboard_data.climate_is_valid = true;
    g_dashboard_data.motion_is_calibrated = true;

    TEST_ASSERT_EQUAL_INT(OLED_SERVICE_STATUS_OK,
                          oled_service_refresh(&g_oled_state,
                                               &g_dashboard_data,
                                               now_ms));
    TEST_ASSERT_TRUE(finish_pending_frame(&now_ms));
    TEST_ASSERT_TRUE(g_captured_data_count >= DISPLAY_FRAME_BYTES);
    memcpy(first_frame, g_captured_data, sizeof(first_frame));

    /* A changed monitored reading must be rendered and sent in a later frame. */
    g_captured_data_count = 0U;
    g_dashboard_data.temperature_tenths_c = 326;
    now_ms += REFRESH_STEP_MS;
    TEST_ASSERT_EQUAL_INT(OLED_SERVICE_STATUS_OK,
                          oled_service_refresh(&g_oled_state,
                                               &g_dashboard_data,
                                               now_ms));
    TEST_ASSERT_TRUE(finish_pending_frame(&now_ms));
    TEST_ASSERT_TRUE(g_captured_data_count >= DISPLAY_FRAME_BYTES);
    TEST_ASSERT_TRUE(memcmp(first_frame,
                            g_captured_data,
                            DISPLAY_FRAME_BYTES) != 0);
}
